const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

const item = $input.first().json;
// Two entry shapes: errorTrigger execution vs sweep webhook payload.
const isErrTrigger = Boolean(item.execution ?? item.workflow);
let failures = [];
if (isErrTrigger) {
  failures = [{ kind: 'execution_error',
    workflow: (item.workflow ?? {}).name ?? 'unknown',
    node: (item.execution ?? {}).lastNodeExecuted ?? 'unknown',
    message: String(item.message ?? item.error ?? ''), retryCount: 0 }];
} else {
  const b = item.body ?? item;
  failures = (b.failures ?? []).map(f => ({ kind: 'sweep', ...f, retryCount: f.retryCount ?? 0 }));
}
return failures.map(f => ({ json: f }));

const f = $input.first().json;
const msg = String(f.message ?? '');
const spendBlocked = /payment|billing|402|insufficient\s*funds|quota_exceeded.*paid|card\s*declined/i.test(msg);
const retryable = !spendBlocked && /timeout|timed out|429|rate\s*limit|5\d\d|ECONN|ENOTFOUND|socket|overload|temporarily/i.test(msg);
const permanent = /unauthor|forbidden|validation|invalid|not\s*allowed|ig_eligibility_failed|fb_page_verification_failed/i.test(msg);
return [{ json: { ...f, spendBlocked, retryable, permanent,
  strategy: spendBlocked ? 'park_spend_guard' : retryable ? 'bounded_retry' : 'park_manual' } }];

console.log('[error-recovery] SPEND GUARD — no auto-spend');
return [{ json: { ...$input.first().json, state: 'NEEDS_REVIEW',
  reason: 'spend_guard_blocked' } }];

const f = $input.first().json;
const n = Number(f.retryCount ?? 0);
const budgetLeft = n < 3;
return [{ json: { ...f, retryCount: n + 1, budgetLeft,
  backoffNote: 'attempt ' + (n + 1) + ' of 3, 5-min interval' } }];

const f = $input.first().json;
return [{ json: { ...f, state: 'NEEDS_REVIEW', manualResume: {
  how: 'Re-trigger the failed workflow webhook with the same idempotencyKey, '
    + 'or fix the input and re-run from the n8n executions panel.',
  context: { workflow: f.workflow, node: f.node, message: f.message } } } }];
